-- gameWE - collector: default data for Microsoft SQL Server.
-- GENERATED by tools/schemagen from the PostgreSQL file: do not edit, run: make schema
-- The same rows as internal/schema/mysql/seed.sql (see there); every INSERT
-- skips the rows whose key exists, so it adds missing rows and changes nothing else.


-- Games (rankings). realgame is the base game a ranking belongs to: it picks
-- the log format, the RCON protocol and the in-game replies (see GAMES.md). A
-- ranking cloned from a game (css1 from css) keeps the template's realgame.
) AS v (code, name, realgame, hidden) WHERE NOT EXISTS (SELECT 1 FROM hlstats_Games t WHERE (t.code = v.code));

-- Team codes as they appear in the logs.
) AS v (game, code, name) WHERE NOT EXISTS (SELECT 1 FROM hlstats_Teams t WHERE (t.game = v.game AND t.code = v.code));

-- Player actions (for_PlayerActions = '1'): skill reward_player for the player.
-- Team actions (for_TeamActions = '1'): skill reward_team for every player of
-- the winning team. The code is the trigger as logged.
) AS v (game, code, reward_player, reward_team, team, description, for_PlayerActions, for_TeamActions) WHERE NOT EXISTS (SELECT 1 FROM hlstats_Actions t WHERE (t.game = v.game AND t.code = v.code));

) AS v (game, code, name, modifier) WHERE NOT EXISTS (SELECT 1 FROM hlstats_Weapons t WHERE (t.game = v.game AND t.code = v.code));

-- ---------------------------------------------------------------------------
-- Counter-Strike: Source (css): the HLstatsX definition data of the gameWE
-- production database (actions/events with rewards, weapons with modifiers,
-- teams, roles, awards, ranks, ribbons, clan tag patterns). Only definitions:
-- no players, clans, counters or award winners.
-- ---------------------------------------------------------------------------

-- Actions (events) with rewards: player actions, player-vs-player actions, team actions
  -- GunGame (logged by the GunGame plugin; values of gr.gameme.com/actions/css5)
  (N'css', N'gg_levelup', N'1', N'0', N'', N'GunGame Level Up', N'1', N'0', N'0', N'0'),
  (N'css', N'gg_leveldown', N'-5', N'0', N'', N'GunGame Level Down', N'1', N'0', N'0', N'0'),
  (N'css', N'gg_win', N'50', N'0', N'', N'GunGame Won', N'1', N'0', N'0', N'0')
) AS v (game, code, reward_player, reward_team, team, description, for_PlayerActions, for_PlayerPlayerActions, for_TeamActions, for_WorldActions) WHERE NOT EXISTS (SELECT 1 FROM hlstats_Actions t WHERE (t.game = v.game AND t.code = v.code));

-- Weapons with skill modifiers
) AS v (game, code, name, modifier) WHERE NOT EXISTS (SELECT 1 FROM hlstats_Weapons t WHERE (t.game = v.game AND t.code = v.code));

-- Teams
) AS v (game, code, name, hidden) WHERE NOT EXISTS (SELECT 1 FROM hlstats_Teams t WHERE (t.game = v.game AND t.code = v.code));

-- Roles (player models)
) AS v (game, code, name, hidden) WHERE NOT EXISTS (SELECT 1 FROM hlstats_Roles t WHERE (t.game = v.game AND t.code = v.code));

-- Daily awards (W = weapon, O = action); winners are computed by the web/cron
) AS v (awardType, game, code, name, verb) WHERE NOT EXISTS (SELECT 1 FROM hlstats_Awards t WHERE (t.game = v.game AND t.code = v.code));

-- Ranks and ribbons
) AS v (definition_type, game_code, code, name, img_file, thumb_file, minimum, restriction_type) WHERE NOT EXISTS (SELECT 1 FROM hlstats_Definition_Ranks_Ribbons t WHERE (t.game_code = v.game_code AND t.definition_type = v.definition_type AND t.name = v.name AND t.code = v.code));

-- Ribbon classes
) AS v (game_code, name, maximum, steps, class) WHERE NOT EXISTS (SELECT 1 FROM hlstats_Definition_Ribbons_Classes t WHERE (t.game_code = v.game_code AND t.class = v.class));

-- ---------------------------------------------------------------------------
-- The other games: definitions of HLstatsX:CE (sql/install.sql of
-- github.com/A1mDev/hlstatsx-community-edition) for cstrike, dod, dods,
-- valve, tf, hl2mp and csgo, plus gameWE additions: csgo weapons CE lacks
-- (knife variants, MP5-SD, ...); csgo award and ribbon codes as CS:GO and the
-- plugin log them (inferno, sg556, mvp instead of CE's firebomb, sg553,
-- round_mvp); the player-history awards (most_kills, ...)
-- and latency for every game; css ranks and ribbon classes for every game, one
-- ribbon per daily award. Left out: CE's player-vs-player award types P/V,
-- and its meta awards mostkills, suicide, bonuspoints, allsentrykills
-- (covered by most_kills, most_suicides, ...; teamkills comes at the end of
-- this file). Rows above win: INSERT IGNORE keeps the first.
-- ---------------------------------------------------------------------------

-- Teams
) AS v (game, code, name, hidden) WHERE NOT EXISTS (SELECT 1 FROM hlstats_Teams t WHERE (t.game = v.game AND t.code = v.code));

